import sys,json
from pathlib import Path
p=Path(sys.argv[1]);events=json.loads(p.read_text())['traceEvents'];main=next((e['pid'],e['tid']) for e in events if e.get('name')=='thread_name' and e.get('args',{}).get('name')=='CrRendererMain');marks={e['name']:e['ts'] for e in events if e['name'].startswith('GH_REQUEST_')};tasks=[e for e in events if e.get('ph')=='X' and e['name']=='RunTask' and (e['pid'],e['tid'])==main];rows=[]
for i in range(1,7):
 start,end=marks['GH_REQUEST_BEGIN_'+str(i)],marks['GH_REQUEST_END_'+str(i)];overlap=[e for e in tasks if e['ts']<=end and e['ts']+e['dur']>=start];maximum=max(overlap,key=lambda e:e['dur']);children=[e for e in events if e.get('ph')=='X' and e.get('dur',0)>1000 and (e.get('pid'),e.get('tid'))==main and maximum['ts']<=e['ts'] and e['ts']+e['dur']<=maximum['ts']+maximum['dur']];rows.append({'case':i,'maxTaskMs':maximum['dur']/1000,'tasks':len(overlap),'topEvents':[{'name':e['name'],'durationMs':e['dur']/1000} for e in sorted(children,key=lambda e:-e['dur'])[:12]]})
out={'scope':'Desktop Chromium RunTask on CrRendererMain, overlapping final confirmation through two animation frames after command completion. Includes layout/paint, untruncated overlapping tasks. Native tracing adds overhead; not iPhone evidence.','results':rows,'maximumMs':max(r['maxTaskMs'] for r in rows)};Path(sys.argv[2]).write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out))
